@staticmethod
def prepare_current_slot_for_template(
    current_step: Optional[FlowStep],
) -> tuple:
    """Prepare the current slot information for the template.

    Args:
        current_step: The current step in the flow.

    Returns:
        A tuple of the collect information slot name and its description.
    """
    return (
        (current_step.collect, current_step.description)
        if isinstance(current_step, CollectInformationFlowStep)
        else (None, None)
    )
